export const commissionTiers = [
  { min: 1, max: 15, perSale: 30 },
  { min: 16, max: 20, perSale: 40 },
  { min: 21, max: 30, perSale: 50 },
  { min: 31, max: 39, perSale: 70 },
  { min: 40, max: 9999, perSale: 90 },
] as const;

export function commissionPerSale(validSales: number) {
  const tier = commissionTiers.find((t) => validSales >= t.min && validSales <= t.max);
  return tier ? tier.perSale : 0;
}

